/* Generated by equipe-design emit — do not edit by hand; change the tokens and emit again. */
/* Light is the default. Dark follows prefers-color-scheme and can be forced with <html data-theme="dark|light">. */
:root {
  color-scheme: light dark;
  /* color */
  --eq-color-background: #ffffff;
  --eq-color-surface: #f7f7f7;
  --eq-color-raised: #fafafa;
  --eq-color-text: #1a1a1a;
  --eq-color-muted-text: #717171;
  --eq-color-primary: #2b2b2b;
  --eq-color-on-primary: #ffffff;
  --eq-color-secondary: #f1f1f1;
  --eq-color-accent: #2456c9;
  --eq-color-border: #e1e1e1;
  --eq-color-border-strong: #818181;
  --eq-color-ring: #2b2b2b;
  --eq-color-destructive: #c62828;
  --eq-color-success: #1b7a43;
  --eq-color-warning: #8f5b00;

  /* font */
  --eq-font-family-sans: 'Hanken Grotesk', Pretendard, 'Noto Sans KR', sans-serif;
  --eq-font-family-mono: 'JetBrains Mono', ui-monospace, monospace;
  --eq-font-weight-regular: 400;
  --eq-font-weight-semibold: 600;

  /* space */
  --eq-space-1: 2px;
  --eq-space-2: 4px;
  --eq-space-3: 8px;
  --eq-space-4: 12px;
  --eq-space-5: 16px;
  --eq-space-6: 24px;
  --eq-space-7: 32px;
  --eq-space-8: 48px;

  /* radius */
  --eq-radius-sm: 4px;
  --eq-radius-md: 6px;
  --eq-radius-lg: 10px;
  --eq-radius-full: 9999px;

  /* shadow */
  --eq-shadow-1: 0px 4px 14px 0px #0000001a;

  /* motion */
  --eq-duration-fast: 140ms;
  --eq-duration-base: 240ms;
  --eq-duration-slow: 400ms;

  /* motion */
  --eq-easing-standard: cubic-bezier(0.4, 0, 0.2, 1);

  /* type roles: weight size/line-height family */
  --eq-type-display: 600 40px/1.25 var(--eq-font-family-sans);
  --eq-type-display-tracking: -0.01em;
  --eq-type-h1: 600 33px/1.25 var(--eq-font-family-sans);
  --eq-type-h1-tracking: -0.01em;
  --eq-type-h2: 600 28px/1.25 var(--eq-font-family-sans);
  --eq-type-h2-tracking: -0.01em;
  --eq-type-h3: 600 23px/1.25 var(--eq-font-family-sans);
  --eq-type-h3-tracking: -0.01em;
  --eq-type-body: 400 16px/1.6 var(--eq-font-family-sans);
  --eq-type-body-tracking: 0em;
  --eq-type-small: 400 13px/1.6 var(--eq-font-family-sans);
  --eq-type-small-tracking: 0em;
  --eq-type-mono: 400 13px/1.6 var(--eq-font-family-mono);
  --eq-type-mono-tracking: 0em;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --eq-color-background: #111113;
    --eq-color-surface: #1d1d1f;
    --eq-color-raised: #29292b;
    --eq-color-text: #eeeeee;
    --eq-color-muted-text: #9a9a9b;
    --eq-color-primary: #f2f2f2;
    --eq-color-on-primary: #000000;
    --eq-color-secondary: #26262a;
    --eq-color-accent: #8ab0ff;
    --eq-color-border: #2e2e2f;
    --eq-color-border-strong: #8b8b8b;
    --eq-color-ring: #f2f2f2;
    --eq-color-destructive: #ff7b72;
    --eq-color-success: #4cc38a;
    --eq-color-warning: #e8b44a;
  }
}
:root[data-theme="light"] { color-scheme: light; }
:root[data-theme="dark"] {
  color-scheme: dark;
  --eq-color-background: #111113;
  --eq-color-surface: #1d1d1f;
  --eq-color-raised: #29292b;
  --eq-color-text: #eeeeee;
  --eq-color-muted-text: #9a9a9b;
  --eq-color-primary: #f2f2f2;
  --eq-color-on-primary: #000000;
  --eq-color-secondary: #26262a;
  --eq-color-accent: #8ab0ff;
  --eq-color-border: #2e2e2f;
  --eq-color-border-strong: #8b8b8b;
  --eq-color-ring: #f2f2f2;
  --eq-color-destructive: #ff7b72;
  --eq-color-success: #4cc38a;
  --eq-color-warning: #e8b44a;
}
